        Scanner sc = new Scanner(System.in);

        int T = sc.nextInt();

        while (T-- > 0) {
            int N = sc.nextInt();

            long prev = 0;
            long ans = 0;

            for (int i = 1; i <= N; i++) {
                long x = sc.nextLong();

                // Transform according to parity
                if (i % 2 == 1) {
                    x = -x;
                }

                if (i == 1) {
                    ans += Math.abs(x);
                } else {
                    ans += Math.abs(x - prev);
                }

                prev = x;
            }

            // Add |B[N]|
            ans += Math.abs(prev);

            System.out.println(ans / 2);
        }

        sc.close();
    }
}

