#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct SegmentTree {
    int n;
    vector<long long> max_val, lazy, sum_val;

    SegmentTree(int n) : n(n) {
        max_val.assign(4 * (n + 2), 0);
        lazy.assign(4 * (n + 2), 0);
        sum_val.assign(4 * (n + 2), 0);
        build(1, 1, n, n + 1);
    }

    void build(int node, int start, int end, int default_val) {
        lazy[node] = 0;
        if (start == end) {
            max_val[node] = default_val;
            sum_val[node] = default_val;
            return;
        }
        int mid = start + (end - start) / 2;
        build(2 * node, start, mid, default_val);
        build(2 * node + 1, mid + 1, end, default_val);
        sum_val[node] = sum_val[2 * node] + sum_val[2 * node + 1];
        max_val[node] = max(max_val[2 * node], max_val[2 * node + 1]);
    }

    inline void apply(int node, int start, int end, long long val) {
        lazy[node] = val;
        max_val[node] = val;
        sum_val[node] = val * (end - start + 1);
    }

    void push(int node, int start, int end) {
        if (lazy[node] != 0) {
            int mid = start + (end - start) / 2;
            apply(2 * node, start, mid, lazy[node]);
            apply(2 * node + 1, mid + 1, end, lazy[node]);
            lazy[node] = 0;
        }
    }

    int find_first(int node, int start, int end, int ql, int qr, long long val) {
        if (start > qr || end < ql || max_val[node] <= val) {
            return -1;
        }
        if (start == end) {
            return start;
        }
        push(node, start, end);
        int mid = start + (end - start) / 2;
        int res = find_first(2 * node, start, mid, ql, qr, val);
        if (res != -1) return res;
        return find_first(2 * node + 1, mid + 1, end, ql, qr, val);
    }

    void update(int node, int start, int end, int ql, int qr, long long val) {
        if (start > qr || end < ql) return;
        if (ql <= start && end <= qr) {
            apply(node, start, end, val);
            return;
        }
        push(node, start, end);
        int mid = start + (end - start) / 2;
        update(2 * node, start, mid, ql, qr, val);
        update(2 * node + 1, mid + 1, end, ql, qr, val);
        sum_val[node] = sum_val[2 * node] + sum_val[2 * node + 1];
        max_val[node] = max(max_val[2 * node], max_val[2 * node + 1]);
    }

    long long query(int node, int start, int end, int ql, int qr) {
        if (start > qr || end < ql) return 0;
        if (ql <= start && end <= qr) return sum_val[node];
        push(node, start, end);
        int mid = start + (end - start) / 2;
        return query(2 * node, start, mid, ql, qr) + query(2 * node + 1, mid + 1, end, ql, qr);
    }
};

struct Pair {
    long long sum;
    int i, j;
    bool operator<(const Pair& other) const {
        return sum > other.sum;
    }
};

void solve() {
    int n;
    if (!(cin >> n)) return;

    vector<long long> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }

    vector<Pair> pairs;
    pairs.reserve(n);
    vector<int> st;
    st.reserve(n);

    for (int j = 1; j <= n; ++j) {
        while (!st.empty() && a[st.back()] < a[j]) {
            st.pop_back();
        }
        if (!st.empty()) {
            int i = st.back();
            if (a[i] > a[j]) {
                pairs.push_back({a[i] + a[j], i, j});
            }
        }
        st.push_back(j);
    }

    sort(pairs.begin(), pairs.end());

    SegmentTree tree(n);
    long long total_ans = 0;

    for (const auto& p : pairs) {
        int i = p.i;
        int j = p.j;
        long long val = p.sum;

        int first_idx = tree.find_first(1, 1, n, 1, i, j);
        if (first_idx != -1) {
            long long old_sum = tree.query(1, 1, n, first_idx, i);
            long long new_sum = (long long)(i - first_idx + 1) * j;
            long long diff = old_sum - new_sum;
            total_ans += diff * val;
            tree.update(1, 1, n, first_idx, i, j);
        }
    }

    cout << total_ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}
